import{bV as t,aL as r,u as o,G as e}from"./chunks/framework.BfzMay2U.js";const c=JSON.parse('{"title":"制造业 PHP 面试题：系统集成与设备联网（51—75）","description":"","frontmatter":{"title":"制造业 PHP 面试题：系统集成与设备联网（51—75）","date":"2026-11-15T10:20:00.000Z","categories":["面试","PHP"],"tags":["系统集成","ERP","MES","API","设备联网","MQTT"],"sidebarSort":3},"headers":[],"relativePath":"php/jd/integration-device-interview.md","filePath":"php/jd/integration-device-interview.md"}'),n={name:"php/jd/integration-device-interview.md"};function s(h,a,i,l,p,d){return r(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="制造业-php-面试题-系统集成与设备联网-51—75" tabindex="-1">制造业 PHP 面试题：系统集成与设备联网（51—75） <a class="header-anchor" href="#制造业-php-面试题-系统集成与设备联网-51—75" aria-label="Permalink to &quot;制造业 PHP 面试题：系统集成与设备联网（51—75）&quot;">​</a></h1><p>集成面试的重点是解释数据从哪里来、以谁为准、怎样防重、失败怎样恢复。本篇沿着工单下发、报工回传、质量记录与入库同步展开。</p><h2 id="一、接口契约与安全" tabindex="-1">一、接口契约与安全 <a class="header-anchor" href="#一、接口契约与安全" aria-label="Permalink to &quot;一、接口契约与安全&quot;">​</a></h2><h3 id="_51-erp、mes、oa、e-dhr-分别负责什么" tabindex="-1">51. ERP、MES、OA、E-DHR 分别负责什么？ <a class="header-anchor" href="#_51-erp、mes、oa、e-dhr-分别负责什么" aria-label="Permalink to &quot;51. ERP、MES、OA、E-DHR 分别负责什么？&quot;">​</a></h3><p><strong>参考回答：</strong> ERP 通常负责资源计划、采购与财务相关业务，MES 负责车间执行，OA 承载行政或审批流程，E-DHR 汇集与器械生产历史相关的受控电子记录。实际职责存在产品和企业差异，应先画业务边界，确定每类主数据和状态由谁维护。</p><p><strong>追问要点：</strong> 不能让四个系统都随意修改同一工单状态；要定义权威来源、允许回写的字段、事件触发点和冲突处理人。</p><h3 id="_52-新对接一家-erp-第一步做什么" tabindex="-1">52. 新对接一家 ERP，第一步做什么？ <a class="header-anchor" href="#_52-新对接一家-erp-第一步做什么" aria-label="Permalink to &quot;52. 新对接一家 ERP，第一步做什么？&quot;">​</a></h3><p><strong>参考回答：</strong> 先对齐业务对象和时序，再确认接口。至少形成系统职责、字段映射、编码规则、状态转换、数量单位、唯一键、鉴权、错误码、超时、重试、对账和验收清单。确定测试环境及双方联系人，使用同一组样例串通完整链路。</p><p><strong>追问要点：</strong> 不要只拿到 URL 就开发；需先确认“接口接收成功”是否代表“业务单据已过账”，以及如何查询最终结果。</p><h3 id="_53-主数据编码不一致时怎样处理" tabindex="-1">53. 主数据编码不一致时怎样处理？ <a class="header-anchor" href="#_53-主数据编码不一致时怎样处理" aria-label="Permalink to &quot;53. 主数据编码不一致时怎样处理？&quot;">​</a></h3><p><strong>参考回答：</strong> 明确物料、产品、工厂、仓库和单位的权威来源，维护带来源系统及有效期的映射。未知编码不能默默转换成默认值，应进入待处理状态；映射变更需评估已发生业务记录是否仍使用原版本。</p><p><strong>场景追问：</strong> 同一物料编码在不同工厂含义不同，映射键必须包含工厂范围。名称可变化，不能拿名称作为长期关联键。</p><h3 id="_54-一份可联调的接口文档要包含哪些内容" tabindex="-1">54. 一份可联调的接口文档要包含哪些内容？ <a class="header-anchor" href="#_54-一份可联调的接口文档要包含哪些内容" aria-label="Permalink to &quot;54. 一份可联调的接口文档要包含哪些内容？&quot;">​</a></h3><p><strong>参考回答：</strong> 除路径、方法和字段外，还应写明身份权限、数据范围、必填与可空、时间格式、单位精度、版本、幂等键、分页方式、错误码、状态含义和示例。异步接口还要给出结果查询、回调鉴权、超时和重放规则。</p><p><strong>追问要点：</strong> 加入重复、冲突、部分失败和已处理的示例；文档和测试契约一起维护，避免代码已改而供应商仍按旧版调用。</p><h3 id="_55-接口幂等键应该怎样设计" tabindex="-1">55. 接口幂等键应该怎样设计？ <a class="header-anchor" href="#_55-接口幂等键应该怎样设计" aria-label="Permalink to &quot;55. 接口幂等键应该怎样设计？&quot;">​</a></h3><p><strong>参考回答：</strong> 用稳定标识表达同一个业务动作，例如来源系统、单据号、行号与动作版本；同一动作重试必须复用同一个键。键的范围应能区分冲销和重新确认等合法新动作，不能仅用工单号阻止该工单所有后续报工。</p><p><strong>追问要点：</strong> 同键不同内容应冲突，摘要计算要采用约定的规范化方式。幂等记录保留时间要覆盖可能的补传和人工重放窗口。</p><h3 id="_56-接口身份认证和数据签名有什么区别" tabindex="-1">56. 接口身份认证和数据签名有什么区别？ <a class="header-anchor" href="#_56-接口身份认证和数据签名有什么区别" aria-label="Permalink to &quot;56. 接口身份认证和数据签名有什么区别？&quot;">​</a></h3><p><strong>参考回答：</strong> 认证确认调用方身份，授权限制其可操作的业务范围，签名验证约定内容未被篡改且来自持有密钥的一方。可按双方能力采用服务凭证、OAuth2、HMAC 等方案，传输仍应使用 TLS。凭证应独立分配、按最小权限配置并支持轮换。</p><p><strong>追问要点：</strong> HMAC 是共享密钥校验，不能直接等同于具有独立身份和记录绑定要求的电子签名；密钥也不能下发给普通小程序客户端。</p><h3 id="_57-如何防止签名接口被重放" tabindex="-1">57. 如何防止签名接口被重放？ <a class="header-anchor" href="#_57-如何防止签名接口被重放" aria-label="Permalink to &quot;57. 如何防止签名接口被重放？&quot;">​</a></h3><p><strong>参考回答：</strong> 签名覆盖约定的方法、路径、时间戳、nonce 和请求体摘要；校验签名后，在有效窗口内原子记录调用方与 nonce，拒绝重复使用。时间窗口要考虑允许的时钟偏差，但不能靠时间戳单独防重。</p><p><strong>追问要点：</strong> URL 编码、JSON 序列化、字段顺序和原始 body 的签名规则必须一致；签名比较使用安全比较函数，并且业务层继续做幂等。</p><h3 id="_58-http-状态码和业务错误码应该怎样分工" tabindex="-1">58. HTTP 状态码和业务错误码应该怎样分工？ <a class="header-anchor" href="#_58-http-状态码和业务错误码应该怎样分工" aria-label="Permalink to &quot;58. HTTP 状态码和业务错误码应该怎样分工？&quot;">​</a></h3><p><strong>参考回答：</strong> HTTP 表达请求层面的结果，例如未认证、禁止访问、输入不合法、资源冲突和服务不可用；业务码表达“物料未放行”“工单已关闭”等具体原因。成功响应还要区分已接收与已完成，避免客户端只看 200 就认定已扣料或入库。</p><p><strong>追问要点：</strong> <code>202 Accepted</code> 表示接受异步处理，应返回任务标识与查询方式；不能把所有错误都返回 200 再让调用方猜测。</p><h2 id="二、可靠同步与异常闭环" tabindex="-1">二、可靠同步与异常闭环 <a class="header-anchor" href="#二、可靠同步与异常闭环" aria-label="Permalink to &quot;二、可靠同步与异常闭环&quot;">​</a></h2><h3 id="_59-外部接口超时-是否可以直接重试" tabindex="-1">59. 外部接口超时，是否可以直接重试？ <a class="header-anchor" href="#_59-外部接口超时-是否可以直接重试" aria-label="Permalink to &quot;59. 外部接口超时，是否可以直接重试？&quot;">​</a></h3><p><strong>参考回答：</strong> 超时只能说明未在期限内拿到结果，不能证明对方未处理。查询类请求通常可按限额重试，写入类请求需先具备稳定幂等键和结果查询能力，再按契约查询或重发；无法确认的状态进入待核对，而非创建新的业务流水。</p><p><strong>场景追问：</strong> ERP 已生成入库单但响应丢失，重试必须引用原来源单号，否则会造成重复入库。</p><h3 id="_60-哪些错误应该重试-哪些不应该" tabindex="-1">60. 哪些错误应该重试，哪些不应该？ <a class="header-anchor" href="#_60-哪些错误应该重试-哪些不应该" aria-label="Permalink to &quot;60. 哪些错误应该重试，哪些不应该？&quot;">​</a></h3><p><strong>参考回答：</strong> 网络故障、部分临时服务错误、限流可按接口契约采用有上限的指数退避与抖动，限流还应尊重 <code>Retry-After</code>。字段缺失、编码错误和业务规则拒绝通常需要修正数据，不能机械重试。状态未知则先查询确认。</p><p><strong>追问要点：</strong> 认证失败应检查配置或按受控流程刷新凭证，不能每条任务都无限刷新。设置最大次数、最大时长、并发上限和人工处理入口。</p><h3 id="_61-为什么生产关键链路常采用-outbox" tabindex="-1">61. 为什么生产关键链路常采用 Outbox？ <a class="header-anchor" href="#_61-为什么生产关键链路常采用-outbox" aria-label="Permalink to &quot;61. 为什么生产关键链路常采用 Outbox？&quot;">​</a></h3><p><strong>参考回答：</strong> 它解决本地业务提交与发送事件不能原子完成的问题。在报工事务中同时写待发送事件，后台提交后扫描发送，记录尝试和结果；这样业务成功后即使进程崩溃，也能继续找到未发送事件。</p><p><strong>关键边界：</strong> 远端成功后、本地标记前仍可能崩溃，因此 outbox 通常提供至少一次发送，消费者仍必须幂等。扫描器还需安全领取任务、处理超时占用并监控积压。</p><h3 id="_62-消息队列能保证-exactly-once-吗" tabindex="-1">62. 消息队列能保证 Exactly Once 吗？ <a class="header-anchor" href="#_62-消息队列能保证-exactly-once-吗" aria-label="Permalink to &quot;62. 消息队列能保证 Exactly Once 吗？&quot;">​</a></h3><p><strong>参考回答：</strong> 不能把中间件某个范围的语义直接扩展为跨 MySQL、HTTP 和 ERP 的业务保证。工程上常按至少一次投递设计，通过业务唯一键、事务和消费记录让重复执行不产生重复效果，再用对账发现遗漏。</p><p><strong>追问要点：</strong> ACK 丢失和消费者崩溃会触发重投；外部副作用与本地消费标记之间仍存在一致性窗口，必须逐个边界分析。</p><h3 id="_63-工单事件乱序到达怎么办" tabindex="-1">63. 工单事件乱序到达怎么办？ <a class="header-anchor" href="#_63-工单事件乱序到达怎么办" aria-label="Permalink to &quot;63. 工单事件乱序到达怎么办？&quot;">​</a></h3><p><strong>参考回答：</strong> 每个业务对象携带来源版本或序号，拒绝覆盖较新状态，必要时等待缺失前序、查询来源快照或进入异常队列。消息分区可改善同一工单内的顺序，但不能取代消费者对版本和状态转换的检查。</p><p><strong>追问要点：</strong> 时间戳存在时钟偏差和同一时刻多事件问题，不宜作为唯一顺序依据。版本是否连续、是否允许跳过，要由事件契约说明。</p><h3 id="_64-一次批量同步中部分明细失败-怎么设计返回和重试" tabindex="-1">64. 一次批量同步中部分明细失败，怎么设计返回和重试？ <a class="header-anchor" href="#_64-一次批量同步中部分明细失败-怎么设计返回和重试" aria-label="Permalink to &quot;64. 一次批量同步中部分明细失败，怎么设计返回和重试？&quot;">​</a></h3><p><strong>参考回答：</strong> 先确定业务要求整单原子还是逐行独立，返回每行稳定标识、状态、错误码及可否重试。若逐行处理，成功行无需重复执行，失败行按原幂等键补传；整单要求则应拒绝部分入账，或由明确的业务补偿流程恢复。</p><p><strong>追问要点：</strong> HTTP 请求整体成功不代表每一行成功，必须记录批次与明细结果，避免按返回条数推断已成功的具体记录。</p><h3 id="_65-对方只有同步-http-接口-没有幂等能力怎么办" tabindex="-1">65. 对方只有同步 HTTP 接口，没有幂等能力怎么办？ <a class="header-anchor" href="#_65-对方只有同步-http-接口-没有幂等能力怎么办" aria-label="Permalink to &quot;65. 对方只有同步 HTTP 接口，没有幂等能力怎么办？&quot;">​</a></h3><p><strong>参考回答：</strong> 先争取让对方按来源单号唯一或提供业务结果查询；本地串行和锁只能减少并发重复，无法消除远端成功、响应丢失的窗口。无法改造时将不确定结果隔离、停止自动重发，并通过查询报表或人工核对确认后继续。</p><p><strong>追问要点：</strong> 应明确这项能力限制和业务处理责任，不能承诺“加一个 Redis 锁就绝不重复”。</p><h3 id="_66-对账应该比对什么-而不只是总数量" tabindex="-1">66. 对账应该比对什么，而不只是总数量？ <a class="header-anchor" href="#_66-对账应该比对什么-而不只是总数量" aria-label="Permalink to &quot;66. 对账应该比对什么，而不只是总数量？&quot;">​</a></h3><p><strong>参考回答：</strong> 按来源单号和明细行比较存在性、数量、单位、批次、状态、版本及必要的业务金额。划定时间水位，给正常同步延迟留窗口，区分缺失、重复、冲突和状态未知，产出可执行的问题清单。</p><p><strong>追问要点：</strong> 总量相同可能掩盖两条明细互相抵消。对账发现差异后先确认权威来源，再通过受控补传或冲销修复，不能直接覆盖两边数据。</p><h3 id="_67-死信和人工补偿怎样做到可控" tabindex="-1">67. 死信和人工补偿怎样做到可控？ <a class="header-anchor" href="#_67-死信和人工补偿怎样做到可控" aria-label="Permalink to &quot;67. 死信和人工补偿怎样做到可控？&quot;">​</a></h3><p><strong>参考回答：</strong> 保存失败事件、业务键、脱敏摘要、尝试次数、最后错误和下次动作。操作台支持查询、复核和按原键重放，修改 payload 应产生新版本并保留原因；关键冲销需要授权审批。</p><p><strong>追问要点：</strong> 重放前检查远端是否已成功，重放后重新对账。补偿本身也可能失败，必须有状态、审计和明确责任人。</p><h3 id="_68-如何监控一条完整的生产数据交互链路" tabindex="-1">68. 如何监控一条完整的生产数据交互链路？ <a class="header-anchor" href="#_68-如何监控一条完整的生产数据交互链路" aria-label="Permalink to &quot;68. 如何监控一条完整的生产数据交互链路？&quot;">​</a></h3><p><strong>参考回答：</strong> 为一次请求生成关联 ID，异步事件再保留事件 ID、来源单号和因果关系。监控成功率、业务拒绝率、处理耗时、积压年龄、重试次数、死信及对账差异，告警应能定位到业务对象和处理入口。</p><p><strong>追问要点：</strong> “HTTP 全部 200”不能证明业务健康；长时间没有事件可能意味着采集停了，应监控预期流量、心跳和最后成功时间。</p><h2 id="三、设备联网与数据采集" tabindex="-1">三、设备联网与数据采集 <a class="header-anchor" href="#三、设备联网与数据采集" aria-label="Permalink to &quot;三、设备联网与数据采集&quot;">​</a></h2><h3 id="_69-php-是否适合直接连接所有-plc-采集数据" tabindex="-1">69. PHP 是否适合直接连接所有 PLC 采集数据？ <a class="header-anchor" href="#_69-php-是否适合直接连接所有-plc-采集数据" aria-label="Permalink to &quot;69. PHP 是否适合直接连接所有 PLC 采集数据？&quot;">​</a></h3><p><strong>参考回答：</strong> 通常应区分设备采集层和业务接收层。PLC、串口或工业协议由适配的采集程序或网关处理，Laravel 接收标准化事件，完成设备身份、业务关联、校验、存储和追溯。已有合适采集组件应优先复用。</p><p><strong>追问要点：</strong> 高频实时控制、设备安全联锁不能依赖普通 Web 请求或不稳定公网；业务系统也不能在未明确授权与验证时向设备发送控制命令。</p><h3 id="_70-modbus、opc-ua、mqtt-有什么区别" tabindex="-1">70. Modbus、OPC UA、MQTT 有什么区别？ <a class="header-anchor" href="#_70-modbus、opc-ua、mqtt-有什么区别" aria-label="Permalink to &quot;70. Modbus、OPC UA、MQTT 有什么区别？&quot;">​</a></h3><p><strong>参考回答：</strong> Modbus 常面向寄存器等数据读取，需约定地址、类型、字节序和缩放；OPC UA 提供较丰富的信息模型及安全能力；MQTT 是发布订阅消息协议，需要另外定义主题、payload 和业务语义。实际由设备能力、网络与安全要求共同决定。</p><p><strong>追问要点：</strong> 能订阅到 MQTT 消息不代表知道它属于哪个工单；协议连通与业务数据正确是两个验收层次。</p><h3 id="_71-设备采集记录最少应保留哪些信息" tabindex="-1">71. 设备采集记录最少应保留哪些信息？ <a class="header-anchor" href="#_71-设备采集记录最少应保留哪些信息" aria-label="Permalink to &quot;71. 设备采集记录最少应保留哪些信息？&quot;">​</a></h3><p><strong>参考回答：</strong> 设备身份、点位或参数、原始值、转换值、单位、质量标志、事件时间、接收时间、来源序号、网关和协议映射版本。与工单、工序、批次的绑定应有明确依据，无法确定时先保留未关联状态。</p><p><strong>追问要点：</strong> 不要根据“这台设备当前工单”直接给迟到数据绑定新批次，应按采集时刻的有效绑定或记录携带的生产标识匹配。</p><h3 id="_72-设备断线后补传-如何防重与识别数据缺口" tabindex="-1">72. 设备断线后补传，如何防重与识别数据缺口？ <a class="header-anchor" href="#_72-设备断线后补传-如何防重与识别数据缺口" aria-label="Permalink to &quot;72. 设备断线后补传，如何防重与识别数据缺口？&quot;">​</a></h3><p><strong>参考回答：</strong> 网关使用持久化缓冲，事件带设备、启动会话和递增序号或稳定事件 ID；服务端唯一约束防重，通过序号缺口及心跳识别异常。设备重启可能清零序号，不能只用设备 ID 加序号长期唯一。</p><p><strong>追问要点：</strong> 补传区分采集时间与接收时间，监控缓冲容量和最老事件年龄；断电前未持久化的样本可能永久丢失，必须说明实际保证范围。</p><h3 id="_73-设备时间不准、数值越界或单位错误怎样处理" tabindex="-1">73. 设备时间不准、数值越界或单位错误怎样处理？ <a class="header-anchor" href="#_73-设备时间不准、数值越界或单位错误怎样处理" aria-label="Permalink to &quot;73. 设备时间不准、数值越界或单位错误怎样处理？&quot;">​</a></h3><p><strong>参考回答：</strong> 保留原始数据和质量标志，将时钟偏差、协议无效值、业务越界分别判断；明确单位与缩放版本，异常数据进入隔离或待复核。不能无记录地“修正”原值，也不能把通讯失败填成测量值零。</p><p><strong>追问要点：</strong> 自动判定是否放行必须使用经确认的有效数据和规则版本。时钟同步解决时间偏差，但不能证明传感器已校准或测量有效。</p><h3 id="_74-mqtt-qos-2-是否意味着生产系统绝不会重复扣料" tabindex="-1">74. MQTT QoS 2 是否意味着生产系统绝不会重复扣料？ <a class="header-anchor" href="#_74-mqtt-qos-2-是否意味着生产系统绝不会重复扣料" aria-label="Permalink to &quot;74. MQTT QoS 2 是否意味着生产系统绝不会重复扣料？&quot;">​</a></h3><p><strong>参考回答：</strong> 不是。QoS 约束的是协议参与方之间的消息交付过程，不能覆盖应用写库、网关重启后重放或调用 ERP 的完整副作用。业务仍要有事件唯一标识和事务幂等，不能在每次收到参数消息时直接无条件扣料。</p><p><strong>追问要点：</strong> 保留消息可能在订阅后重新送达旧状态，离线会话也影响补发；需要明确主题区分“最新状态”和“不可重复的业务事件”。</p><h3 id="_75-设备供应商说-数据没问题-你怎样组织联调" tabindex="-1">75. 设备供应商说“数据没问题”，你怎样组织联调？ <a class="header-anchor" href="#_75-设备供应商说-数据没问题-你怎样组织联调" aria-label="Permalink to &quot;75. 设备供应商说“数据没问题”，你怎样组织联调？&quot;">​</a></h3><p><strong>参考回答：</strong> 选一个已知工单和标准样本，从设备原始读数、网关解析、消息内容、接收日志到数据库逐层核对；固定点位映射、单位、采样频率和时间，记录双方版本及预期。覆盖断网、重启、重复、乱序、异常值和恢复补传。</p><p><strong>追问要点：</strong> 用同一个事件 ID 或来源序号关联证据，把问题定位到具体边界；形成责任人、修复期限、复测和最终关闭记录。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./mysql-concurrency-interview.html">上一篇：MySQL、并发与报表（26—50）</a></li><li><a href="./mes-edhr-oa-interview.html">下一篇：MES、E-DHR 与 OA（76—100）</a></li><li><a href="./../">返回 PHP 面试指南</a></li><li><a href="./../advanced/system-integration-api.html">既有专题：系统接口设计与集成</a></li><li><a href="./../projects/device-connectivity-data-collection.html">既有专题：设备联网与数据采集</a></li></ul>',82)])])}const u=t(n,[["render",s]]);export{c as __pageData,u as default};
